using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using DepartmentFinancialRecords.API.Data;using DepartmentFinancialRecords.API.Models;
namespace DepartmentFinancialRecords.API.Controllers;
[ApiController][Route("api/records")]public sealed class RecordsController:ControllerBase{private readonly ApplicationDbContext _db;public RecordsController(ApplicationDbContext db)=>_db=db;[HttpGet("attendance-events")]public async Task<IActionResult> Events()=>Ok(await _db.AttendanceEvents.AsNoTracking().ToListAsync());[HttpPost("attendance-events")]public async Task<IActionResult> AddEvent(AttendanceEvent x){_db.AttendanceEvents.Add(x);await _db.SaveChangesAsync();return Created($"api/records/attendance-events/{x.Id}",x);}[HttpGet("attendance")]public async Task<IActionResult> Attendance()=>Ok(await _db.AttendanceRecords.Include(x=>x.Student).Include(x=>x.AttendanceEvent).AsNoTracking().ToListAsync());[HttpPost("attendance")]public async Task<IActionResult> AddAttendance(AttendanceRecord x){_db.AttendanceRecords.Add(x);await _db.SaveChangesAsync();return Created("api/records/attendance",x);}[HttpGet("collections")]public async Task<IActionResult> Collections()=>Ok(await _db.Collections.Include(x=>x.Student).AsNoTracking().ToListAsync());[HttpPost("collections")]public async Task<IActionResult> AddCollection(Collection x){_db.Collections.Add(x);await _db.SaveChangesAsync();return Created("api/records/collections",x);}[HttpGet("collectibles")]public async Task<IActionResult> Collectibles()=>Ok(await _db.Collectibles.Include(x=>x.Student).AsNoTracking().ToListAsync());[HttpPost("collectibles")]public async Task<IActionResult> AddCollectible(Collectible x){_db.Collectibles.Add(x);await _db.SaveChangesAsync();return Created("api/records/collectibles",x);}[HttpGet("fines")]public async Task<IActionResult> Fines()=>Ok(await _db.Fines.Include(x=>x.Student).AsNoTracking().ToListAsync());[HttpPost("fines")]public async Task<IActionResult> AddFine(Fine x){_db.Fines.Add(x);await _db.SaveChangesAsync();return Created("api/records/fines",x);}[HttpGet("fund-transactions")]public async Task<IActionResult> Funds()=>Ok(await _db.FundTransactions.AsNoTracking().ToListAsync());[HttpPost("fund-transactions")]public async Task<IActionResult> AddFund(FundTransaction x){_db.FundTransactions.Add(x);await _db.SaveChangesAsync();return Created("api/records/fund-transactions",x);}[HttpGet("disbursements")]public async Task<IActionResult> Disbursements()=>Ok(await _db.Disbursements.AsNoTracking().ToListAsync());[HttpPost("disbursements")]public async Task<IActionResult> AddDisbursement(Disbursement x){_db.Disbursements.Add(x);await _db.SaveChangesAsync();return Created("api/records/disbursements",x);}[HttpGet("activity-logs")]public async Task<IActionResult> Logs()=>Ok(await _db.ActivityLogs.Include(x=>x.User).AsNoTracking().ToListAsync());}
